$(document).ready(function () {
  ($(".wp1").waypoint(
    function () {
      $(".wp1").addClass("animated fadeInLeft");
    },
    { offset: "75%" },
  ),
    $(".wp2").waypoint(
      function () {
        $(".wp2").addClass("animated fadeInRight");
      },
      { offset: "75%" },
    ),
    $(".wp3").waypoint(
      function () {
        $(".wp3").addClass("animated fadeInLeft");
      },
      { offset: "75%" },
    ),
    $(".wp4").waypoint(
      function () {
        $(".wp4").addClass("animated fadeInRight");
      },
      { offset: "75%" },
    ),
    $(".wp5").waypoint(
      function () {
        $(".wp5").addClass("animated fadeInLeft");
      },
      { offset: "75%" },
    ),
    $(".wp7").waypoint(
      function () {
        $(".wp7").addClass("animated fadeInUp");
      },
      { offset: "75%" },
    ),
    $(".wp8").waypoint(
      function () {
        $(".wp8").addClass("animated fadeInLeft");
      },
      { offset: "75%" },
    ),
    $(".wp9").waypoint(
      function () {
        $(".wp9").addClass("animated fadeInRight");
      },
      { offset: "75%" },
    ),
    (function () {
      // galerie "A bientôt" : 2 photos visibles sur téléphone, 3 sur tablette, 5 sur ordinateur
      var gallery = $(".gallery-carousel");
      function visible() {
        var w = window.innerWidth;
        return w < 768 ? 2 : w < 992 ? 3 : 5;
      }
      gallery.flexslider({
        animation: "slide",
        animationLoop: !0,
        itemWidth: 220,
        itemMargin: 12,
        minItems: visible(),
        maxItems: visible(),
        move: 1,
        slideshow: !0,
        slideshowSpeed: 4e3,
        pauseOnHover: !0,
        controlNav: !1,
      });
      $(window).on("resize", function () {
        var slider = gallery.data("flexslider");
        if (slider) slider.vars.minItems = slider.vars.maxItems = visible();
      });
    })(),
    $(".fancybox").fancybox({ padding: 4, width: 1e3, height: 800 }),
    $(".nav-toggle").click(function () {
      ($(this).toggleClass("active"),
        $(".header-nav").toggleClass("open"),
        event.preventDefault());
    }),
    $(".header-nav li a").click(function () {
      ($(".nav-toggle").toggleClass("active"),
        $(".header-nav").toggleClass("open"));
    }),
    $(function () {
      $(window).scroll(function () {
        20 <= $(window).scrollTop()
          /* ÉTAT "SCROLLÉ" */
          ? ($("section.navigation").addClass("fixed"),
            $("header").css({ "border-bottom": "none", padding: "25px 0" }),
            $("header .member-actions").css({ top: "16px" }),
            $("header .navicon").css({ top: "23px" }))
          : ($("section.navigation").removeClass("fixed"),
          /* ÉTAT "EN HAUT DE PAGE" */
            $("header").css({
              "border-bottom": "solid 1px rgba(255, 255, 255, 0.2)",
              padding: "30px 0",
            }),
            $("header .member-actions").css({ top: "21px" }),
            $("header .navicon").css({ top: "28px" }));
      });
    }),
    $(function () {
      $("a[href*=#]:not([href=#])").click(function () {
        if (
          location.pathname.replace(/^\//, "") ===
            this.pathname.replace(/^\//, "") &&
          location.hostname === this.hostname
        ) {
          var e = $(this.hash);
          if (
            (e = e.length ? e : $("[name=" + this.hash.slice(1) + "]")).length
          )
            return (
              $("html,body").animate({ scrollTop: e.offset().top - 90 }, 2e3),
              !1
            );
        }
      });
    }));
});
